CREATE TABLE IF NOT EXISTS `equipes` (Id int AUTO_INCREMENT PRIMARY KEY, EquipeId int NOT NULL, CriadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, AtualizadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, `Nome` varchar(255) NOT NULL, `NomeFantasia` varchar(255) NOT NULL, `Logo` varchar(255) NOT NULL, `Telefone` varchar(255) NOT NULL, `Whatsapp` varchar(255) NOT NULL, `Email` varchar(190) NOT NULL, `Site` varchar(255) NOT NULL, `Cep` varchar(255) NOT NULL, `Endereco` varchar(255) NOT NULL, `Numero` varchar(255) NOT NULL, `Bairro` varchar(255) NOT NULL, `Cidade` varchar(255) NOT NULL, `Estado` varchar(255) NOT NULL, `Status` varchar(255) NOT NULL, INDEX ix_equipes_equipe(EquipeId)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `faixas` (Id int AUTO_INCREMENT PRIMARY KEY, EquipeId int NOT NULL, CriadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, AtualizadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, `Nome` varchar(255) NOT NULL, `Cor` varchar(255) NOT NULL, `Ordem` int NOT NULL, `MesesMinimos` int NOT NULL, INDEX ix_faixas_equipe(EquipeId)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `graus` (Id int AUTO_INCREMENT PRIMARY KEY, EquipeId int NOT NULL, CriadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, AtualizadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, `Nome` varchar(255) NOT NULL, `Numero` int NOT NULL, INDEX ix_graus_equipe(EquipeId)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `unidades` (Id int AUTO_INCREMENT PRIMARY KEY, EquipeId int NOT NULL, CriadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, AtualizadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, `Nome` varchar(255) NOT NULL, `Tipo` varchar(255) NOT NULL, `ResponsavelId` int NULL, `Telefone` varchar(255) NOT NULL, `Whatsapp` varchar(255) NOT NULL, `Email` varchar(190) NOT NULL, `Cep` varchar(255) NOT NULL, `Endereco` varchar(255) NOT NULL, `Numero` varchar(255) NOT NULL, `Bairro` varchar(255) NOT NULL, `Cidade` varchar(255) NOT NULL, `Estado` varchar(255) NOT NULL, `Complemento` varchar(255) NOT NULL, `Status` varchar(255) NOT NULL, INDEX ix_unidades_equipe(EquipeId)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `professores` (Id int AUTO_INCREMENT PRIMARY KEY, EquipeId int NOT NULL, CriadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, AtualizadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, `Nome` varchar(255) NOT NULL, `UnidadeId` int NOT NULL, `Cpf` varchar(255) NOT NULL, `DataNascimento` date NULL, `Telefone` varchar(255) NOT NULL, `Whatsapp` varchar(255) NOT NULL, `Email` varchar(190) NOT NULL, `Foto` varchar(255) NOT NULL, `FaixaId` int NOT NULL, `GrauId` int NOT NULL, `DataEntrada` date NOT NULL, `DataGraduacao` date NULL, `ProfessorResponsavelId` int NULL, `Status` varchar(255) NOT NULL, `Observacoes` text NOT NULL, INDEX ix_professores_equipe(EquipeId)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `planos` (Id int AUTO_INCREMENT PRIMARY KEY, EquipeId int NOT NULL, CriadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, AtualizadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, `Nome` varchar(255) NOT NULL, `Valor` decimal(12,2) NOT NULL, `DiaVencimento` int NOT NULL, `Status` varchar(255) NOT NULL, INDEX ix_planos_equipe(EquipeId)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `alunos` (Id int AUTO_INCREMENT PRIMARY KEY, EquipeId int NOT NULL, CriadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, AtualizadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, `Nome` varchar(255) NOT NULL, `UnidadeId` int NOT NULL, `Cpf` varchar(255) NOT NULL, `DataNascimento` date NULL, `Sexo` varchar(255) NOT NULL, `Telefone` varchar(255) NOT NULL, `Whatsapp` varchar(255) NOT NULL, `Email` varchar(190) NOT NULL, `Cep` varchar(255) NOT NULL, `Endereco` varchar(255) NOT NULL, `Numero` varchar(255) NOT NULL, `Bairro` varchar(255) NOT NULL, `Cidade` varchar(255) NOT NULL, `Estado` varchar(255) NOT NULL, `Foto` varchar(255) NOT NULL, `DataInicio` date NOT NULL, `FaixaId` int NOT NULL, `GrauId` int NOT NULL, `DataUltimaGraduacao` date NULL, `ProfessorResponsavelId` int NOT NULL, `PlanoId` int NULL, `Status` varchar(255) NOT NULL, `Observacoes` text NOT NULL, CodigoPublico char(32) NOT NULL UNIQUE, INDEX ix_alunos_equipe(EquipeId)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `turmas` (Id int AUTO_INCREMENT PRIMARY KEY, EquipeId int NOT NULL, CriadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, AtualizadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, `Nome` varchar(255) NOT NULL, `UnidadeId` int NOT NULL, `ProfessorId` int NOT NULL, `Descricao` text NOT NULL, `DiaSemana` varchar(255) NOT NULL, `HoraInicio` varchar(255) NOT NULL, `HoraFim` varchar(255) NOT NULL, `FaixaMinimaId` int NOT NULL, `FaixaMaximaId` int NOT NULL, `Capacidade` int NOT NULL, `Status` varchar(255) NOT NULL, INDEX ix_turmas_equipe(EquipeId)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `turma_alunos` (Id int AUTO_INCREMENT PRIMARY KEY, EquipeId int NOT NULL, CriadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, AtualizadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, `TurmaId` int NOT NULL, `AlunoId` int NOT NULL, INDEX ix_turma_alunos_equipe(EquipeId), UNIQUE KEY ux_matricula(EquipeId,TurmaId,AlunoId)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `graduacoes` (Id int AUTO_INCREMENT PRIMARY KEY, EquipeId int NOT NULL, CriadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, AtualizadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, `AlunoId` int NOT NULL, `ProfessorId` int NOT NULL, `UnidadeId` int NOT NULL, `FaixaAnteriorId` int NULL, `GrauAnteriorId` int NULL, `FaixaNovaId` int NOT NULL, `GrauNovoId` int NOT NULL, `DataGraduacao` date NOT NULL, `Observacoes` text NOT NULL, INDEX ix_graduacoes_equipe(EquipeId)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `frequencias` (Id int AUTO_INCREMENT PRIMARY KEY, EquipeId int NOT NULL, CriadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, AtualizadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, `TurmaId` int NOT NULL, `AlunoId` int NOT NULL, `UnidadeId` int NOT NULL, `Data` date NOT NULL, `Presente` boolean NOT NULL, INDEX ix_frequencias_equipe(EquipeId), UNIQUE KEY ux_frequencia(EquipeId,TurmaId,AlunoId,Data)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `campeonatos` (Id int AUTO_INCREMENT PRIMARY KEY, EquipeId int NOT NULL, CriadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, AtualizadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, `Nome` varchar(255) NOT NULL, `Data` date NOT NULL, `Local` varchar(255) NOT NULL, `Cidade` varchar(255) NOT NULL, `Organizacao` varchar(255) NOT NULL, `Status` varchar(255) NOT NULL, `Observacoes` text NOT NULL, INDEX ix_campeonatos_equipe(EquipeId)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `inscricoes_campeonatos` (Id int AUTO_INCREMENT PRIMARY KEY, EquipeId int NOT NULL, CriadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, AtualizadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, `CampeonatoId` int NOT NULL, `AlunoId` int NOT NULL, `Categoria` varchar(255) NOT NULL, `FaixaId` int NOT NULL, `Peso` decimal(12,2) NOT NULL, `Idade` int NOT NULL, `Resultado` varchar(255) NOT NULL, `Observacoes` text NOT NULL, INDEX ix_inscricoes_campeonatos_equipe(EquipeId), UNIQUE KEY ux_inscricao(EquipeId,CampeonatoId,AlunoId)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `eventos` (Id int AUTO_INCREMENT PRIMARY KEY, EquipeId int NOT NULL, CriadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, AtualizadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, `Nome` varchar(255) NOT NULL, `Tipo` varchar(255) NOT NULL, `Data` date NOT NULL, `Local` varchar(255) NOT NULL, `UnidadeId` int NOT NULL, `Observacoes` text NOT NULL, INDEX ix_eventos_equipe(EquipeId)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `mensalidades` (Id int AUTO_INCREMENT PRIMARY KEY, EquipeId int NOT NULL, CriadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, AtualizadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, `AlunoId` int NOT NULL, `Competencia` varchar(190) NOT NULL, `Vencimento` date NOT NULL, `Valor` decimal(12,2) NOT NULL, `Status` varchar(255) NOT NULL, `Observacoes` text NOT NULL, INDEX ix_mensalidades_equipe(EquipeId), UNIQUE KEY ux_mensalidade(EquipeId,AlunoId,Competencia)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `recebimentos` (Id int AUTO_INCREMENT PRIMARY KEY, EquipeId int NOT NULL, CriadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, AtualizadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, `MensalidadeId` int NOT NULL, `Data` date NOT NULL, `Valor` decimal(12,2) NOT NULL, `FormaPagamento` varchar(255) NOT NULL, `Observacoes` text NOT NULL, INDEX ix_recebimentos_equipe(EquipeId)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `usuarios` (Id int AUTO_INCREMENT PRIMARY KEY, EquipeId int NOT NULL, CriadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, AtualizadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, `Nome` varchar(255) NOT NULL, `Email` varchar(190) NOT NULL, `Perfil` varchar(255) NOT NULL, `AlunoId` int NULL, `Status` varchar(255) NOT NULL, SenhaHash varchar(500) NOT NULL, INDEX ix_usuarios_equipe(EquipeId), UNIQUE KEY ux_usuario_email(Email)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS permissoes (Id int AUTO_INCREMENT PRIMARY KEY, Nome varchar(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS usuario_permissoes (UsuarioId int NOT NULL, PermissaoId int NOT NULL, PRIMARY KEY(UsuarioId,PermissaoId), FOREIGN KEY(UsuarioId) REFERENCES usuarios(Id) ON DELETE CASCADE, FOREIGN KEY(PermissaoId) REFERENCES permissoes(Id));
CREATE TABLE IF NOT EXISTS certificados (Id int AUTO_INCREMENT PRIMARY KEY, EquipeId int NOT NULL, GraduacaoId int NOT NULL UNIQUE, Codigo char(32) NOT NULL UNIQUE, CriadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(EquipeId) REFERENCES equipes(Id), FOREIGN KEY(GraduacaoId) REFERENCES graduacoes(Id));
CREATE TABLE IF NOT EXISTS configuracoes (Id int AUTO_INCREMENT PRIMARY KEY, EquipeId int NOT NULL, Chave varchar(100) NOT NULL, Valor varchar(255) NOT NULL, CriadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, AtualizadoEm datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY ux_configuracao(EquipeId,Chave), FOREIGN KEY(EquipeId) REFERENCES equipes(Id));